        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "build":
        payload = collect()
        D.mkdir(parents=True, exist_ok=True)
        (D / "lp_long_build.json").write_text(json.dumps(payload))
        for name, row in payload.items():
            print(f"  {name:14s} prompt={row['prompt_tokens']:6d} "
                  f"server={row['server_prompt_tokens']:6d} forced={row['forced_tokens']}")
        return
    if cmd == "save":
        name = sys.argv[2]
        payload = collect()
        D.mkdir(parents=True, exist_ok=True)
        (D / f"lp_long_{name}.json").write_text(json.dumps(payload))
        for key, row in payload.items():
            print(f"  {key:14s} prompt={row['prompt_tokens']:6d} "
                  f"server={row['server_prompt_tokens']:6d} forced={row['forced_tokens']}")
        return
    if cmd == "check":
        name = sys.argv[2]
        reference = json.loads((D / f"lp_long_{name}.json").read_text())
        current = collect(cached=reference)
        report = stats(reference, current)
        print_report(f"{name} vs current", report)
        return
    if cmd == "compare":
        a, b = sys.argv[2], sys.argv[3]
        ra = json.loads((D / f"lp_long_{a}.json").read_text())
        rb = json.loads((D / f"lp_long_{b}.json").read_text())
        print_report(f"{b} vs {a}", stats(ra, rb))
        print_report(f"{a} vs {"    {'OVERALL':<14s} max {overall['max']:.6f}  mean {overall['mean']:.6f}")
    print(f"LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


